"""Fixed additional test routing, never commands generated by the model.
Runs in the unprivileged validation job without API secrets/write tokens.
"""
import os
from pathlib import Path
import socket
import subprocess
import tempfile

from codex_followup import git, require


def run():
    paths = git('.', 'diff', '--name-only', 'HEAD').decode().splitlines()
    # Linux cannot prove macOS native behavior. Do not publish an untested native proposal.
    require(not any(p.startswith('src-tauri/') for p in paths), 'MACOS_NATIVE_VALIDATION_REQUIRED')
    if not any(p.startswith('server/') for p in paths):
        return
    binaries = sorted(Path('/usr/lib/postgresql').glob('*/bin/initdb'))
    require(bool(binaries), 'POSTGRES_TEST_RUNTIME_REQUIRED')
    pg = binaries[-1].parent
    java = os.environ.get('JAVA_HOME_21_X64', os.environ.get('JAVA_HOME', ''))
    require(bool(java), 'JAVA21_REQUIRED')
    with tempfile.TemporaryDirectory(prefix='luma-codex-db-') as directory:
        with socket.socket() as listener:
            listener.bind(('127.0.0.1', 0)); port = listener.getsockname()[1]
        subprocess.run([pg/'initdb', '-D', directory, '-U', 'luma', '-A', 'trust'], check=True, timeout=60)
        subprocess.run([pg/'pg_ctl', '-D', directory, '-l', directory+'/postgres.log', '-o', f'-h 127.0.0.1 -p {port}', 'start'], check=True, timeout=60)
        try:
            subprocess.run([pg/'createdb', '-h', '127.0.0.1', '-p', str(port), '-U', 'luma', 'luma_codex_test'], check=True, timeout=30)
            env = {k:v for k,v in os.environ.items() if not k.startswith(('SPRING_', 'LUMA_DB_', 'LUMA_TEST_DB_'))}
            env.update(JAVA_HOME=java, LUMA_TEST_DB_URL=f'jdbc:postgresql://127.0.0.1:{port}/luma_codex_test', LUMA_TEST_DB_USER='luma', LUMA_TEST_DB_PASSWORD='')
            subprocess.run(['bash', 'server/gradlew', '-p', 'server', 'test', 'bootJar', '--no-daemon'], env=env, check=True, timeout=900)
        finally:
            subprocess.run([pg/'pg_ctl', '-D', directory, 'stop', '-m', 'fast'], check=True, timeout=30)


if __name__ == '__main__': run()
